            Int32,
            vec![Some(5), Some(5), Some(5), Some(5), Some(5)]
        ))
        .unwrap();
        let data_size =
            write_parquet(Arc::clone(&store), "constant.parquet", batch.clone()).await;
        let schema = batch.schema();

        let file = PartitionedFile::new(
